CREATE OR REPLACE FUNCTION public.claim_named_lead_auto_recovery(p_job_id uuid, p_logical_result_id text, p_policy_version text)
 RETURNS TABLE(attempt_token uuid, query text, expected_name text, context_label text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_job public.share_jobs%rowtype;
  v_slot jsonb;
  v_identity jsonb;
  v_prior jsonb;
  v_token uuid := gen_random_uuid();
  v_logical text := trim(p_logical_result_id);
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if length(v_logical) not between 1 and 160 or length(trim(p_policy_version)) not between 1 and 80 then
    raise exception 'invalid_recovery_request';
  end if;
  select * into v_job from public.share_jobs
   where id=p_job_id and user_id=v_uid for update;
  if v_job.id is null then raise exception 'share_job_not_found'; end if;
  if v_job.status not in ('needs_help','failed') then return; end if;

  select s into v_slot from jsonb_array_elements(
    case when jsonb_typeof(v_job.candidate_payload->'mentionSlots')='array'
      then v_job.candidate_payload->'mentionSlots' else '[]'::jsonb end
  ) s where s->>'mentionId'=v_logical limit 1;
  select i into v_identity from jsonb_array_elements(
    case when jsonb_typeof(v_slot->'identityHypotheses')='array'
      then v_slot->'identityHypotheses' else '[]'::jsonb end
  ) i where coalesce(i->>'evidenceKind','observable')='observable'
      and length(trim(coalesce(i->>'name',''))) between 2 and 160 limit 1;
  if v_identity is null then return; end if;

  v_prior := v_job.candidate_payload->'automaticRecovery'->v_logical;
  if v_prior->>'policyVersion'=trim(p_policy_version) and (
    v_prior->>'status' in ('no_match','choice_required','saved') or
    (v_prior->>'status'='searching' and
      coalesce((v_prior->>'attemptedAt')::timestamptz,now()) > now()-interval '5 minutes') or
    (v_prior->>'status'='technical_failure' and
      coalesce((v_prior->>'retryAfter')::timestamptz,now()) > now())
  ) then return; end if;

  update public.share_jobs set candidate_payload=jsonb_set(
    coalesce(candidate_payload,'{}'::jsonb),'{automaticRecovery}',
    coalesce(candidate_payload->'automaticRecovery','{}'::jsonb) || jsonb_build_object(v_logical,
      jsonb_build_object('policyVersion',trim(p_policy_version),'status','searching',
        'attemptToken',v_token,'attemptedAt',now())),true),updated_at=now()
  where id=v_job.id;
  return query select v_token,
    concat_ws(' ',trim(v_identity->>'name'),nullif(trim(coalesce(v_identity->>'contextLabel',v_slot->>'contextLabel')),'')),
    trim(v_identity->>'name'),nullif(trim(coalesce(v_identity->>'contextLabel',v_slot->>'contextLabel')),'');
end;
$function$

CREATE OR REPLACE FUNCTION public.create_share_job_for_user(p_user_id uuid, p_source_url text, p_canonical_url text, p_source_platform text, p_idempotency_key text DEFAULT NULL::text, p_dedupe_window_seconds integer DEFAULT 90, p_is_anonymous boolean DEFAULT false, p_force_rerun boolean DEFAULT false)
 RETURNS TABLE(job_id uuid, status text, duplicate boolean, requires_purchase boolean, available_uses integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_existing record; v_job public.share_jobs%rowtype; v_lock_key bigint; v_available integer:=0;
begin
  if p_user_id is null then raise exception 'missing_user_id'; end if;
  v_lock_key:=hashtextextended(p_user_id::text||':'||coalesce(p_canonical_url,p_source_url,''),0);
  perform pg_advisory_xact_lock(v_lock_key);
  if not p_is_anonymous then
    perform * from public.ensure_place_find_wallet(p_user_id,false);
    select pfw.available_uses into v_available
      from public.place_find_wallets as pfw where pfw.user_id=p_user_id;
  end if;
  if nullif(trim(p_idempotency_key),'') is not null then
    select sj.* into v_existing from public.share_jobs sj
      where sj.user_id=p_user_id and sj.idempotency_key=p_idempotency_key limit 1;
    if found then return query select v_existing.id,v_existing.status,true,false,v_available; return; end if;
  end if;
  select sj.* into v_existing from public.share_jobs sj
    where sj.user_id=p_user_id and sj.canonical_url=p_canonical_url
      and sj.status in ('queued','processing_metadata')
      and sj.created_at>=now()-make_interval(secs=>greatest(p_dedupe_window_seconds,1))
    order by sj.created_at desc limit 1;
  if found then return query select v_existing.id,v_existing.status,true,false,v_available; return; end if;
  if not p_force_rerun then
    select sj.* into v_existing from public.share_jobs sj
      where sj.user_id=p_user_id and sj.canonical_url=p_canonical_url and sj.status='completed'
      order by sj.completed_at desc nulls last,sj.created_at desc limit 1;
    if found then return query select v_existing.id,v_existing.status,true,false,v_available; return; end if;
  end if;
  insert into public.share_jobs(
    user_id,source_url,canonical_url,source_platform,status,progress_stage,
    idempotency_key,billing_mode,billing_outcome,billing_settled_at
  ) values(
    p_user_id,p_source_url,p_canonical_url,p_source_platform,'queued','queued',
    p_idempotency_key,'normal_free','unmetered:normal_free',now()
  ) returning * into v_job;
  return query select v_job.id,v_job.status,false,false,v_available;
end;
$function$

CREATE OR REPLACE FUNCTION public.invoke_process_media_tasks()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_base_url text;
  v_secret text;
begin
  -- Prefer Vault secrets.
  begin
    select decrypted_secret into v_base_url
      from vault.decrypted_secrets
     where name = 'share_media_worker_url'
     limit 1;
  exception when others then
    v_base_url := null;
  end;
  begin
    select decrypted_secret into v_secret
      from vault.decrypted_secrets
     where name = 'share_media_worker_secret'
     limit 1;
  exception when others then
    v_secret := null;
  end;

  -- Fall back to database settings.
  if v_base_url is null or v_base_url = '' then
    v_base_url := nullif(current_setting('app.settings.share_media_worker_url', true), '');
  end if;
  if v_secret is null or v_secret = '' then
    v_secret := nullif(current_setting('app.settings.share_media_worker_secret', true), '');
  end if;

  -- Not configured yet → no-op (never raise). The cron backstop starts
  -- dispatching automatically once the secrets are set.
  if v_base_url is null or v_secret is null then
    return;
  end if;

  perform net.http_post(
    url := rtrim(v_base_url, '/') || '/v1/process-media-tasks',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_secret
    ),
    body := jsonb_build_object('trigger', 'db', 'limit', 2)
  );
exception when others then
  -- pg_net missing / transient failure: swallow. Durability is the persisted
  -- row + the cron sweep, not this call.
  return;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_recognition_revalidation_media_task(p_task_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_task public.recognition_revalidation_tasks%rowtype;
declare v_source public.recognition_source_states%rowtype;
declare v_user_id uuid;
begin
  select * into v_task from public.recognition_revalidation_tasks where id=p_task_id for update;
  if v_task.id is null or v_task.state not in ('QUEUED','RETRY_WAIT') or v_task.next_attempt_at > now() then return false; end if;
  select * into v_source from public.recognition_source_states where identity_key=v_task.identity_key;
  select ce.user_id into v_user_id from public.recognition_correction_events ce where ce.id=v_task.correction_event_id;
  if v_source.identity_key is null or v_user_id is null then return false; end if;
  if exists(select 1 from public.share_media_tasks mt where mt.recognition_revalidation_task_id=v_task.id
    and mt.status in ('queued','processing')) then return false; end if;
  insert into public.share_media_tasks(
    task_kind,recognition_revalidation_task_id,user_id,source_url,canonical_url,
    platform,status,progress_stage,max_attempts,next_attempt_at
  ) values (
    'recognition_revalidation',v_task.id,v_user_id,v_source.canonical_url,v_source.canonical_url,
    v_source.platform,'queued','queued',3,now()
  );
  update public.recognition_revalidation_tasks set state='QUEUED',updated_at=now() where id=v_task.id;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.share_media_tasks_enforce_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_owner uuid; v_target uuid; v_premium_id uuid;
begin
  if new.task_kind in ('recognition','premium_recognition') then
    select sj.user_id,sj.premium_request_id into v_owner,v_premium_id
      from public.share_jobs sj where sj.id=new.share_job_id;
    if v_owner is null then raise exception 'share_media_tasks: parent share_job % not found',new.share_job_id; end if;
    if new.task_kind='premium_recognition' and new.premium_request_id is distinct from v_premium_id then
      raise exception 'share_media_tasks: premium request mismatch';
    end if;
  elsif new.task_kind='ai_note_enrichment' then
    select sp.user_id,sp.place_id into v_owner,v_target from public.saved_places sp where sp.id=new.saved_place_id;
    if v_owner is null or v_target is distinct from new.target_place_id then
      raise exception 'share_media_tasks: invalid ai note target';
    end if;
  elsif new.task_kind='recognition_revalidation' then
    select ce.user_id into v_owner
      from public.recognition_revalidation_tasks rt
      join public.recognition_correction_events ce on ce.id=rt.correction_event_id
     where rt.id=new.recognition_revalidation_task_id;
    if v_owner is null then raise exception 'share_media_tasks: invalid revalidation target'; end if;
  else
    raise exception 'share_media_tasks: invalid task_kind %',new.task_kind;
  end if;
  if new.user_id is distinct from v_owner then raise exception 'share_media_tasks: owner mismatch'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_premium_media_task_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_changed integer;
begin
  if new.task_kind='premium_recognition' and new.status='processing' and old.status is distinct from new.status then
    update public.share_jobs set premium_state='processing',premium_started_at=coalesce(premium_started_at,now()),updated_at=now()
      where id=new.share_job_id and premium_request_id=new.premium_request_id and premium_state='reserved';
    get diagnostics v_changed=row_count;
    if v_changed>0 then
      insert into public.analytics_events(user_id,event_name,properties) values(
        new.user_id,'premium_request_started',jsonb_build_object('share_job_id',new.share_job_id)
      );
    end if;
  end if;
  return new;
end;
$function$
